  <?php foreach($recurringDefinitions as $definition): $id=(int)$definition['id']; $savedRule=(string)$definition['recurring_rule']; $savedDays=[]; if(preg_match('/^weekly_days:([1-7](?:,[1-7])*)$/',$savedRule,$savedMatch))$savedDays=array_map('intval',explode(',',$savedMatch[1])); ?>
