/span></label><?php endforeach;?></fieldset><label><span>Repeat time</span><input type="time" name="due_time" value="<?= htmlspecialchars(substr((string)$definition['due_time'],0,5),ENT_QUOTES,'UTF-8') ?>" required></label><label><span>Start date</span><input type="date" name="start_date" value="<?= htmlspecialchars((string)($definition['start_date']??''),ENT_QUOTES,'UTF-8') ?>"></label><label><span>End date</span><input type="date" name="end_date" value="<?= htmlspecialchars((string)($definition['end_date']??''),ENT_QUOTES,'UTF-8') ?>"></label></div><p>Changes apply to future generated occurrences only. Completed and already-generated task history is not rewritten.</p><footer><button type="button" data-recurring-edit-close>Cancel</button><button type="submit">Save Future Rule</button></footer></form></dialog>
